import json
customers = {i: {'id': i, 'region': 'eu' if i % 2 else 'us'} for i in range(100)}
orders = [{'id': i, 'customer_id': i % 100, 'amount': i * 3} for i in range(500)]
totals = {}
for order in orders:
    region = customers[order['customer_id']]['region']
    totals[region] = totals.get(region, 0) + order['amount']
print(json.dumps({'dataset': 'revenue_by_region', 'rows': len(totals), 'totals': totals}, sort_keys=True))
